189	    /** The import box: lines of name,grade,terms,contact (the last two may be absent or blank), blank lines
190	     *  skipped. Every line is checked first with the person form's rules, a name or contact repeated within
191	     *  the import too (ignoring case); a refused line refuses the import, adding no one and writing nothing.
192	     *  Otherwise each is added in order, exactly as the form adds them. The people added, in line order. */
193	    @Transactional
194	    public List<Person> importPeople(String sheetId, String user, String text) {
195	        requireSheet(sheetId);
196	        List<ImportLine> lines = new ArrayList<>();
197	        Set<String> names = new HashSet<>();
198	        Set<String> contacts = new HashSet<>();
199	        Set<String> tree = namesInTree(sheetId, null);
200	        String[] raw = text == null ? new String[0] : text.split("\\r?\\n");
201	        for (int i = 0; i < raw.length; i++) {
202	            if (raw[i].isBlank()) {
203	                continue;
204	            }
205	            ImportLine line = parseImport(i + 1, raw[i]);
206	            String lower = line.name().toLowerCase(Locale.ROOT);
207	            if (!names.add(lower)) {
208	                throw importRefused(line.number(), "the name " + line.name() + " is already in this import.");
209	            }
210	            if (people.nameTaken(sheetId, line.name(), null) || tree.contains(lower)) {
211	                throw importRefused(line.number(), "the name " + line.name() + " is already in use.");
212	            }
213	            if (line.contact() != null) {
214	                if (!contacts.add(line.contact())) {
215	                    throw importRefused(line.number(), "the contact " + line.contact() + " is already in this import.");
216	                }
217	                if (people.contactTaken(sheetId, line.contact(), null)) {
218	                    throw importRefused(line.number(), "the contact " + line.contact() + " is already in use.");
219	                }
220	            }
221	            lines.add(line);
222	        }
223	        if (lines.isEmpty()) {
224	            throw new PersonImportException("Paste at least one line of name,grade,terms,contact.");
225	        }
226	        List<Person> added = new ArrayList<>();
227	        for (ImportLine line : lines) {
228	            try {
229	                added.add(add(sheetId, user, line.name(), line.grade(), line.terms(), line.contact()));
230	            } catch (PersonNameTakenException | PersonContactTakenException e) {
231	                // taken by another user at the same moment
232	                throw importRefused(line.number(), e.getMessage());
233	            }
234	        }
235	        return added;
236	    }
