238	    private static ImportLine parseImport(int number, String raw) {
239	        String[] f = raw.split(",", 4);
240	        String name = f[0].trim();
241	        if (name.isEmpty()) {
242	            throw importRefused(number, "enter a name.");
243	        }
244	        if (name.length() > 200) {
245	            throw importRefused(number, "the name is too long.");
246	        }
247	        String grade = f.length > 1 ? f[1].trim() : "";
248	        if (!grade.matches("[ABC]")) {
249	            throw importRefused(number, "choose a grade of A, B or C.");
250	        }
251	        String terms = f.length > 2 ? f[2].trim() : "";
252	        if (!terms.isEmpty() && !terms.matches("\\d{1,6}")) {
253	            throw importRefused(number, "enter the terms as a whole number of days, or leave them blank.");
254	        }
255	        String contact = f.length > 3 ? f[3].trim() : "";
256	        if (contact.length() > 200) {
257	            throw importRefused(number, "enter a contact of at most 200 characters.");
258	        }
259	        return new ImportLine(number, name, grade, terms.isEmpty() ? null : Integer.valueOf(terms),
260	                contactKey(contact));
261	    }
