360	     *  dates kept, listed after the other's in the order they were added, each losing any figure a statement
361	     *  bound); their name and aliases become the other's aliases; their patrons are added to the other's (not
362	     *  themselves, no repeats), anyone naming them as patron names the other instead (no repeats), and their
363	     *  pool memberships move to the other (shares added, at most 100.00, where the other is already a member)
364	     *  as do their figures for closed periods. Their statements, holds, watchers and contact are dropped, and
365	     *  they leave the sheet. Refused for anyone but a steward, for the same person, and when either is
366	     *  retired. */
367	    @Transactional
368	    public Person merge(String sheetId, String user, long personId, long intoId) {
369	        Person from = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
370	        Person into = people.findByIdAndSheetId(intoId, sheetId).orElseThrow(PersonNotFoundException::new);
371	        if (!roles.isSteward(sheetId, user)) {
372	            throw new MergeRefusedException("Only a steward may merge people.");
373	        }
374	        if (from.getId().equals(into.getId())) {
375	            throw new MergeRefusedException("A person cannot be merged into themselves.");
376	        }
377	        if (from.isRetired() || into.isRetired()) {
378	            throw new MergeRefusedException("A retired person cannot be merged.");
379	        }
380	        Rollup.Snapshot before = rollup.take(sheetId);
381	        List<Claim> moving = new ArrayList<>(
382	                claims.findForUpdateBySheetIdAndPersonIdOrderByListOrderDesc(sheetId, from.getId()));
383	        moving.sort(Comparator.comparing(Claim::getId));
384	        long order = claims.maxListOrder(sheetId);
385	        for (Claim claim : moving) {
386	            claim.setPersonId(into.getId());
387	            claim.setStated(false, null);
388	            claim.setListOrder(++order);
389	        }
390	        claims.saveAll(moving);
391	
392	        List<Long> intoPatrons = new ArrayList<>(patronsOf(into.getId()));
393	        for (Patron patron : patrons.findByPersonIdOrderByIdAsc(from.getId())) {
394	            if (!patron.getPatronId().equals(into.getId()) && !intoPatrons.contains(patron.getPatronId())) {
395	                patrons.save(new Patron(sheetId, into.getId(), patron.getPatronId()));
396	                intoPatrons.add(patron.getPatronId());
397	            }
398	            patrons.delete(patron);
399	        }
400	        for (Patron patron : patrons.findBySheetIdOrderByIdAsc(sheetId)) {
401	            if (!patron.getPatronId().equals(from.getId())) {
402	                continue;
403	            }
404	            if (!patron.getPersonId().equals(into.getId())
405	                    && !patrons.existsByPersonIdAndPatronId(patron.getPersonId(), into.getId())) {
406	                patrons.save(new Patron(sheetId, patron.getPersonId(), into.getId()));
407	            }
408	            patrons.delete(patron);
409	        }
410	
411	        for (Pool pool : pools.findBySheetIdOrderByIdAsc(sheetId)) {
412	            if (pool.hasMember(from.getId())) {
413	                pool.moveMember(from.getId(), into.getId());
414	            }
415	        }
416	        for (Period period : periods.findBySheetIdOrderByFromDateAsc(sheetId)) {
417	            period.moveClosedTotal(from.getId(), into.getId());
418	        }
419	        watches.deleteAll(watches.findByPersonIdOrderByIdAsc(from.getId()));
420	        statements.deleteAll(statements.findByPersonIdOrderByIdAsc(from.getId()));
421	        // everything naming them goes before they do
422	        people.flush();
423	
424	        List<String> names = new ArrayList<>();
425	        names.add(from.getName());
426	        names.addAll(from.getAliases());
427	        people.delete(from);
428	        people.flush();
429	        names.forEach(into::addAlias);
430	        Person merged = people.saveAndFlush(into);
431	        audit.recordOnCommit("PERSON_MERGED sheet=" + sheetId + " by=" + user + " from=" + from.getName()
432	                + " into=" + merged.getName());
433	        rollup.recordChanges(sheetId, user, before);
434	        return merged;
435	    }
